/** siman 444 part 2 — Erev Pesach on Shabbat */
export const fixes = {
  "output/siman_444/beur-hagra/part-001.txt": {
    "1:א": "Seif 1 — \"We search...\" As is stated there in siman 1 seif 1; and now that we rule as stated; Ramban regarding the time... and as stated in the Yerushalmi there; and I brought it in siman 453 seif 11.",
    "1:ב": "\"And we burn...\" In the Rambam there — R' Elazar of Bartuta there 13:1; he holds accordingly and the halachah was decided according to him — Rambam. Not like the Rif, who wrote that R' Elazar bar Tzadok holds like R' Elazar b. Zadok and holds that what is written \"and we burn everything...\" refers to the end regarding terumah; and see in the hasagot there.",
    "1:ג": "\"And we leave over.\" There 13:1.",
    "1:ד": "\"For the meal.\" See what is stated siman 291 seif 2.",
    "1:ה": "\"Not with matzah.\" As stated in the Yerushalmi chapter 7 of Pesach, and the Rif and Rosh brought it in chapter 3 of Pesachim there — one who eats matzah on Erev Pesach...",
    "1:ו": "\"Rather... and one must.\" As Rashi stated chapter Erev Pesachim — one shall not eat... and they said there 107:2 that close to minchah ketanah... and there 100:2 here before the ninth hour etc. And Tosafos wrote there 99:2 s.v. \"lo ye'achel\"... and if you ask... one may answer that it deals with matzah ashirah... and the Rosh wrote that thus was the practice of Rabbenu Tam on Erev Pesach when it fell on Shabbat...",
    "1:ז": "\"And in lands... one fulfills...\" For there is a dispute among poskim whether specifically bread or types of delicacies, and they decided according to those who say specifically bread; but where it is impossible one may rely etc., and as stated siman 291 seif 6; and see what is stated there. And one may do this even after the tenth hour as stated there 107:2 — and not like Tosafos, for Tosafos' proof that matzah ashirah is permitted on Erev Pesach from their question on what is stated on Erev Pesach close to minchah etc.; see there Tosafos on Erev Pesach 99:2 s.v. \"samuch\" — but Rambam explained there that it is stated and it is impossible to say that eating is forbidden in them; and as stated in siman 471 a little in seif 6. And as stated, therefore we do not practice with cooked matzah either; and so too in Zohar parashat Emor that this meal is entirely deferred — from which we learn that there is no remedy for the matter at all. And as the Rashba wrote that one does not fulfill the third meal except with bread, and it is impossible at all as stated above; and see Magen Avraham what he wrote in the name of the Mordechai and Bach and Kol Bo — and such is the main point.",
    "1:ח": "\"Or.\" Magen Avraham.",
    "2:_": "Seif 2 — \"and on the day.\" There 7:1 — granted regarding Shabbat...",
    "3:א": "Seif 3 — \"one does not.\" Taz — and rinsing not for the sake of eating is forbidden as stated in chapter 16 of Shabbos.",
    "3:ב": "\"And if...\" Magen Avraham; and see Tosafos 6:1 s.v. \"kofeh\". Alternatively...",
    "4:א": "Seif 4 — \"on condition that he not.\" Magen Avraham; and as stated in the Yerushalmi — one does not give to a non-Jew on condition that he go out, as stated in siman 325; see there.",
    "4:ב": "\"To the public domain.\" Taz; and likewise in siman 325 it is an issur of shevut shevut in a place of mitzvah as stated in chapter 6 of Eruvin.",
    "4:ג": "\"And a small amount.\" Magen Avraham; and as stated in Shabbos — one gives food; and Tosafos wrote specifically food — as Rambam wrote \"to eat them.\"",
    "5:א": "Seif 5 — \"if remains.\" As stated in seif 2.",
    "5:ב": "\"And covers.\" As stated there on Yom Tov.",
    "6:_": "Seif 6 — \"even though.\" Perhaps something remains, as stated siman 434 seif 2.",
    "7:א": "Seif 7 — \"and if he went out.\" The wording of the Rambam.",
    "7:ב": "\"Up to an egg's volume.\" Like the Sages.",
    "7:ג": "\"Less than this\" — and likewise Rashi there and likewise Yerushalmi there; and Tosafos brought it s.v. \"vechachamim.\"",
    "8:_": "Seif 8 — \"but if.\" In the Gemara there."
  },
  "output/siman_444/biur-halacha/part-001.txt": {
    "1:א": "\"And we leave over food for two meals\" — he stated two because by law one is not obligated to burn it until close to Shabbat; and if so, at the time of burning he leaves only two meals for the sake of Shabbat. And according to our custom in seif 2, that one burns everything before noon as in other years, one may leave more than two meals if he wishes to eat more before the night; and likewise Rambam wrote unspecifiedly: and one leaves from the chametz in order to eat from it until the fourth hour on Shabbat day; and likewise the Mordechai in the ma'amar.",
    "1:ב": "\"For the sake of Shabbat\" — see in responsa regarding one who forgot to separate challah from chametz bread on this Erev Shabbat — for according to Magen Avraham below in siman 486, that bread has no remedy to eat on Erev Shabbat in seif kaf 8; and he brought in the name of responsum of Peri Megadim to be lenient on Erev Shabbat; and according to his words I found in Sefer Bigdei Yesha siman 486 and in Netiv Chayim there and in Chiddushei R' Akiva Eiger — and all agree that in a place of pressing need one may separate even on Shabbat challah outside the Land, and the challah he gives to a minor kohen less than nine years, or to an adult who immersed for his keri; and see there further in Noda B'Yehuda and Yad Efrayim what they further wrote on this; and see in Peri Megadim there. And even though many later authorities copied Magen Avraham's words for the law [see Eliyah Rabbah and Chayei Yisrael and Chayei Adam and Gra and Derech HaChaim and Chayei Adam] — nevertheless one may rely on the great ones mentioned to be lenient when he has no other bread to eat and so as not to nullify oneg Shabbat, whose obligation is with bread.",
    "7:א": "\"To circumcise his son\" — it is simple that the same applies if he goes to circumcise his friend's son, if the father cannot himself — for behold the obligation is then upon all Israel; and likewise Rambam chapter 3 did not mention at all \"goes to circumcise,\" but rather \"to do a mitzvah\"; see there.",
    "7:ב": "\"Betrothal meal\" — the later authorities wondered — behold, above in siman 249 it is explained that it is forbidden to make a betrothal meal on Erev Shabbat, and the same on Yom Tov; and many forced answers to this. And in truth there is no difficulty; and this case is different on Erev Pesach — and needless to say if the meal was close to noon, as it appears from what he said \"if he can burn and return to his mitzvah,\" and the time of burning is before noon — if so, necessarily the entire meal is without bread, for chametz is forbidden and matzah is also forbidden then; and it deals only with a general feast that is not forbidden; and on the contrary, much wine is consumed, as is stated in the Gemara. And even if we say the meal was in the morning and because of his meal he would be forced to burn chametz before the time — likewise there is no difficulty; for since in any event he would be forced to stop his meal at the end of the fourth hour because of the prohibition of chametz — this is not in the category of a large meal that they forbade on Erev Shabbat and Yom Tov, and because of \"lest he enter Shabbat when he is not desirous to eat\" — for certainly he will be desirous to eat in the evening, since he is forced to stop at the fourth hour. And this case is different on every Erev Shabbat and Yom Tov, for we are concerned the meal will extend a long time; and akin to our words is explained in Sefer Chak Yosef and Magen Elef. And know further that from the Tur it implies that the second meal of betrothal is not in the category of betrothal meal — only the meal of gifts is like a betrothal meal; and so he explained his words in Beit Yosef; and all the later authorities wondered on him — behold, second meal and meal of gifts are one, as is explained in Rashi in Pesachim 49. And I found in Ittur daf 120 side 2 explicitly like the Beit Yosef's words; and it appears that the Tur's words flow from it.",
    "7:ג": "\"To rescue from the river\" — see Mishna Berurah. And it appears that the same applies if it does not touch saving a life at all — only monetary damage — nullification suffices; if he fears that meanwhile while he is occupied with burning the river will wash his property or another Jew's property. And it is further possible that even if he can return and rescue, the Sages were lenient regarding it to rely on nullification in such a case; and this requires further study for the law.",
    "8:_": "\"And he is occupied elsewhere\" — see Mishna Berurah; and the same when he has no place to bake it, such as in his dog's mouth — and it is simple."
  },
  "output/siman_444/chok-yaakov/part-001.txt": {
    "1:א": "As below siman 462. Even though the matter of siman 462 does not apply — for perhaps only there during Pesach they practice to forbid it, lest one come to eat it on the first night because of the obligation of matzah, as is explained in the Tur and Beit Yosef below siman 462; and Beit Yosef wrote there: and there is no reason in that custom to decree and to be concerned about what the Sages of the Talmud and later authorities were not concerned about — if so, let us not add upon it on Erev Pesach, for there is a good distinguishing mark, for it is forbidden to eat at that time matzah proper; and it is possible that the intent of the Rav is: since in these lands they do not practice on Pesach with matzah ashirah, he did not burden him so much for the sake of the third meal on Erev Pesach to knead matzah ashirah, and one fulfills with kinds of fruit etc.; but where one has matzah ashirah it is permitted to eat it at the third meal, and in this there is no concern of nullifying the custom. However, Maharil, laws of Shabbat HaGadol, and in the gloss in Semak siman 219, also wrote that even on Erev Pesach one should not eat matzah ashirah, lest one be concerned that perhaps a little water became mixed in it and it leavened, even though there is a remedy in guarding according to what is stated below siman 462 — nevertheless we are concerned that one will not perform guarding, since it is fruit juice and it did not enter his mind to be concerned that a little water became mixed in it; and after this the Rav continued:",
    "1:ב": "With kinds of fruit or meat and fish. Even though above siman 291 it is explained that it is better to make it with meat and fish than with fruit — here the Rav wrote fruit first; it appears to me that for matzah eaten for pleasure it is better to fulfill with kinds of fruit, which do not satiate so much; and furthermore, since the way with meat and fish is to dip bread in them, we are concerned lest one come to err and eat matzah with them. And in Magen Avraham he wrote: and also on Erev Pesach it is better to fulfill it with meat and fish — and this is not the meaning of the Rav's wording here, but rather as stated. He also wrote in the name of the Zohar to engage in Torah in place of the third meal; and he wrote in the Maharil: and it is fitting to make it with cooked matzah — and I have not seen people practice thus; end of his words. And the later authorities wrote that nevertheless it is good to make another meal in the morning before the time of burning, since one fulfills with this; Bach:",
    "2:א": "It is good to burn on Erev Shabbat — and according to the law of burning, as will be explained nearby siman 445 seif 1; and in the gloss there see there.",
    "2:ב": "Before noon — as is explained above siman 434. And regarding nullification he did not write that it is good to nullify on Erev Shabbat before the sixth hour, so that one not come to err in other years — for nullification can be done at its time on Shabbat on Erev Pesach like on every Erev Shabbat; not so burning, which is impossible on this Shabbat. This appears to be the intent of the Rama in the gloss, which seemingly is duplicated, for the Mechaber stated explicitly in seif 6; rather his intent is as stated. And see in Magen Avraham, who wants to reconcile the Rama's glosses here as well — in any event there is no need at all to nullify on Erev Shabbat, only at night at the time of burning and on Shabbat; and this is simple. And see above siman 434:",
    "3:_": "And it is impossible to wipe them. And how is it possible — to wipe them is forbidden, to rinse them, since one does not need them, as is explained above siman 323; and likewise Mahariv siman 193. And he further wrote that it is good to cook in new vessels. And see above siman 471:",
    "4:א": "He shall shake out the tablecloth. And those fine crumbs and wiping the bowls — the Rosh wrote that one need not remove them from his domain, for they are trampled and burned by themselves. And Mahariv in siman 193 wrote that if he has no non-Jew to clean the house for him, the Jew may clean by changing his garment; and all the more so where there are floorboards, for there is no concern for a pit; end of his words.",
    "4:ב": "On condition that he not go out with it. This implies; but in an unspecified case it is forbidden with chametz, for it is similar to other objects that were explained above siman 321 — since there is no way to eat the chametz in a Jewish house — and so it appears in the Mordechai chapter 1 of Shabbos according to one opinion; and likewise there in Gidulei Mordechai. And this appears to me to be the simple intent of the Mechaber's wording — and not like Magen Avraham; even though above siman 325 seif 2 in the gloss he wrote that it is permitted to send even by a non-Jew for the sake of a mitzvah, such as to remove chametz from the house on Pesach — nevertheless here he stated unspecifiedly like the Mechaber's words, to forbid, because here it deals with one who still has a remedy for the chametz, such as to give it before his dog or his animal, whose food is upon him, as the Rokeach wrote siman 266; and see above siman 324; or according to the opinion of some poskim to winnow it to the wind, as is explained below siman 446; see there seif kaf 9. And if so there is no need of mitzvah, since it is possible through another matter. And this is what the Mechaber inferred: one may give it to a non-Jew with language of permission; and had it been an obligation of mitzvah, he would have had to write language that one is obligated to give it to a non-Jew — which is not so; above it deals with one who cannot through another matter — then it is a need of mitzvah. As stated, it is simple that it is not like some of the later authorities who force very much to divide in several ways to resolve this difficulty — and their words do not fit the Mechaber's wording and gloss; and as stated, everything is correct.",
    "4:ג": "And a small amount. And if he forgot to sell his chametz that he has in a special room on Erev Shabbat, he must give on Shabbat as a gift to a non-Jew the room with transfer of the key; and it is possible that even selling is also permitted and it is not like buying and selling, which is forbidden on Shabbat, since one is doing only to escape the prohibition of chametz; and similarly Tosafos wrote in Eruvin daf 66 s.v. \"yafeh\" that it is permitted to rent domain from a non-Jew on Shabbat and it is not like buying and selling, since they do only to permit moving objects, as is explained above simanim 482 and 483; see there. Nevertheless, where it is possible through a gift we do so, if he knows that the non-Jew will return it to him after Pesach, as is explained below siman 448:",
    "6:_": "As the way he nullifies in other years. See above siman 455 regarding the law of drawing water when Erev Pesach falls on Shabbat; and see above siman 456 regarding the law if one forgot to separate challah from bread that he baked for the sake of Shabbat and Erev Shabbat. And he wrote in Shaarei Chaim that they should not prolong in prayer to say it calmly on this Shabbat because of eating chametz — and so is the practice.",
    "7:א": "To eat a betrothal meal. And the same law applies to the second meal of gifts, or the purchase meal that they make now at the time of the match — this too is called a meal of mitzvah; even though it is forbidden to make a betrothal meal on Erev Shabbat and all the more so on Erev Pesach. And see what the later authorities wrote to resolve this difficulty. And see in Rambam chapter 5 of Hilchot De'ot, who wrote that it is not called a meal of mitzvah that a Torah scholar is permitted to enjoy from it except a daughter of a Torah scholar to a Torah scholar; and Kesef Mishnah there wrote that this is only from the way of ethics and they did not say in chapter Elu Overin that it is not called a meal of mitzvah except a daughter of a Torah scholar to an am ha'aretz and a daughter of a kohen to an Israelite — not so where both are equal, even though they are amei ha'aretz, it is called a meal of mitzvah. See in the Mordechai chapter \"The place where they practiced\" regarding the law of a meal of mitzvah:",
    "7:ב": "At his father-in-law's house. Not specifically the groom himself; rather the same law applies after one goes to a meal of mitzvah — so it appears from Rambam chapter 3 of Hilchot Chametz uMatzah; and likewise Magen Avraham. And see above siman 551:",
    "7:ג": "He shall nullify it in his heart. And if it is after the time of burning, then he cannot nullify it, as is explained above siman 434 and nearby seif 1 he returns and burns. And Magen Avraham wrote: if he goes to deal with a dead body of mitzvah he does not return and burn.",
    "7:ד": "Even if there is time. And even after the time of burning, when he cannot nullify, and there is still time to rescue — nevertheless he does not return, for we are concerned lest he be preoccupied with his burning and be prevented from saving lives. So too Kesef Mishnah chapter 3 of Hilchot Chametz uMatzah — not like Magen Avraham, who wrote the opposite.",
    "7:ה": "And if he went out for his own need. This follows the wording of the Rambam, who wrote in the Be careful wording of the Beit Yosef that from his language it is clear that he disagrees with the Tur in the name of the Rosh and the Yerushalmi, who ruled that even if one goes to the evening in order to learn Torah he returns — for action is greater than study. Nevertheless it appears that the main point is like the Tur and the Rosh; and so appears the opinion of the later authorities. And even though the Rama did not emend anything here, it is possible that he relied on what is stated at the end of siman 431, that even if he began to learn he must interrupt because of searching for chametz, which is the ultimate burning — all the more so here. And what Magen Avraham asks — why do we say here that he returns because of the mitzvah of burning, which is d'rabbanan, from that which is permitted to become impure in Beit HaPeras, which is d'rabbanan, in order to go learn Torah — see what he answered to this. And in my humble opinion, initially there is no difficulty at all, for we say the reason that action is greater than study implies that specifically an action that is a positive commandment (an example of a positive commandment that overrides a negative commandment) — even d'rabbanan, such as searching and burning chametz — not so impurity in Beit HaPeras, which is only a negative commandment d'rabbanan; and it is simple. And in any event one should not compare this rabbinic decree to that, for sometimes they established their words in place of karet and sometimes they did not establish their words in place of karet — they said and they said, as is explained in responsum of the Rambam siman 127; see there.",
    "7:ו": "Less than this he nullifies. And after the time of burning, when he cannot nullify, he returns up to a k'zayit; and less than this he does not return — such is the implication of the Tosafos at the beginning of chapter Elu Overin in the name of the Yerushalmi; and likewise Magen Avraham."
  },
  "output/siman_444/chokhmat-shlomo/part-001.txt": {
    "1:_": "Seif 1 — \"The 14th when it falls on Shabbat\" etc. NB: Behold, by law if one forgot to separate challah on Erev Pesach that fell on Shabbat — see in Ba'er Heitev, who wrote that one gives the remainder to a minor kohen; and he wondered about this in Sefer Chak Yosef — how did he separate challah initially on Shabbat? And he wondered well. However, according to what is stated in his novellae to the laws of Shabbat siman 563, still in manuscript, one may say that in such a case it helps to take challah in thought — it fits well, for certainly taking the body of the challah is possible in thought; but if one fulfills challah in thought, what shall he do with what he leaves over, since the law of challah applies to it? And in this he wrote well that one gives the remainder to a minor kohen in the manner explained below siman 457. And even though Ba'er Heitev did not intend this, nevertheless for the law he spoke correctly, in my humble opinion; and understand well. I again saw in Shulchan Aruch Shaarei Teshuvah that he brought in the name of Sefer She'eilat Ya'avetz that he ruled thus — and my intent is his opinion; and I do not have this book to examine his reason; and understand well. And behold, see in Magen Avraham here seif kaf 1, who wrote that the morning meal too one should divide into two, for some say that one fulfills thus etc. Behold, according to this one may resolve the explanation of Rashi that is wondrous in chapter 1 of Pesachim [daf 13] s.v. \"mazon shtei se'udot velo shelosh\" — that all three meals are for Shabbat: evening, morning, and minchah; and on Erev Pesach it is forbidden to eat from minchah and above; end of his words. And it is wondrous, for he did not state this reason — for in any event it is forbidden to eat chametz until after the fourth hour; and I already asked about this from the sharp son R' Chaim Yehuda, may he rest in Eden, and from the rabbi of the holy community of Lita — but it appears that it fits well: Rashi holds like the opinion of those who say that one fulfills in the morning in place of the third meal, like the opinion of the one authority that Magen Avraham brought. But Rashi holds that this is not as an obligation — for certainly the main obligation of three meals is at minchah; nevertheless it helps as completion, like in prayer where completion applies, and in the sukkah meal according to R' Eliezer. But Rashi holds that completion applies only if he is obligated at its time and at its season — then completion applies also afterward or before; but if at the time of his main obligation there is no obligation at all, how does completion apply before or after it, since at the time of its main obligation there is no obligation? And like an onen in havdalah, where the poskim wrote this distinction — see in the Rosh and Taz, laws of aninus. And if so, here too this is Rashi's intent: certainly in general, since the main obligation applies at minchah, it also helps beforehand as completion, as if he ate at its time; but on Erev Pesach that falls on Shabbat, since at its main time there is no obligation of the third meal at all — if so, since at his main obligation he is exempt automatically, completion beforehand does not apply. And this is what Rashi said: the Shabbat meal — its main parts are evening, morning, and minchah; and on Erev Pesach it is forbidden to eat from minchah and above — if so, the obligation of the third meal does not apply at all, and completion does not apply here; therefore he leaves only two meals and not three; and to eat it in the morning in place of the third meal — for on this day completion does not apply — and it fits well. And this appears very correct as Rashi's intent, and there is no place to deviate here except as stated; and understand well."
  },
  "output/siman_444/eliyah-rabbah/part-001.txt": {
    "1:_": "(1) \"The fourteenth when it falls\" etc. They should bring water to knead on the night of the fourteenth, and not on Erev Shabbat, lest one precede or delay and desecrate Shabbat (Mateh Moshe). And it appears to me that there is a scribal error and it must say the night of the thirteenth — that is, Thursday night — as Rama wrote siman 455. And Beit Yosef wrote that even during bein hashemashot it is forbidden because of preparation; and the same law applies to those who bake on the second day of Yom Tov — they are forbidden to draw during bein hashemashot on Yom Tov, but rather on the night of Erev Yom Tov. And if one forgot to draw on Thursday night, he draws on Erev Shabbat while it is still day, or commands gentiles to draw during bein hashemashot, or takes drawn water in his house, since it is impossible through another matter (Magen Avraham). And if the cistern is in his courtyard, one may permit through pressing need to fill by many people one after another in small vessels. On Shabbat they should not prolong in prayer, but say it calmly, lest the time of the prohibition of chametz arrive — Sefer Chassidim siman 514. If one forgot to separate challah from chametz dough on Erev Shabbat, it is forbidden to eat from the bread and a remedy does not help to eat and separate tomorrow, as on other Shabbatot — for one must burn it (Magen Avraham siman 486).",
    "2:_": "(2) \"And see above siman 291.\" So one must say; and there I explained it.",
    "3:_": "(3) \"And it is impossible to wipe them\" etc. But where possible it is forbidden to rinse it, as was explained siman 323; and see siman 473 seif kaf 13 — I wrote that it is permitted to put the maror in water; and see siman 459 seif 4 that we dip it to cool it. There are men of action who cook the entire dish in a Yom Tov vessel — Maharam; and therefore one should not put it in a chametz bowl unless when it is not boiling, yad soledes bo, or he pours into another Yom Tov vessel and afterward pours into the chametz bowl; however b'dieved see siman 461 seif kaf 39.",
    "4:_": "(4) [Levush] \"Before the fifth hour\" etc. And know that Magen Avraham at the end of siman 446 holds that it is permitted to move at the fifth hour, since it is fit for dogs.",
    "5:_": "(5) \"On condition\" etc. Not specifically; rather the same law applies in an unspecified case. And so ruled Mateh Moshe and the remainder of Knesset HaGedolah and Magen Avraham. And now it is fine that which he permits in siman 325 seif 2 — for there it deals with one who gives to him in an unspecified manner; and with much chametz it is as if one says to him explicitly to take it out — and not like Olat Shabbat. And see in Chok Yaakov; and I shortened, since we have no public domain — the later authorities wrote that it is permitted to command explicitly. And if there are no gentiles to clean the house, Mahariv wrote that the Jew may clean by garment. And Bach wrote that the custom is to give it to dogs whose food is upon them, and not to a pig. And if it is permitted to scatter to the wind on Shabbat — see siman 446; and in Magen Avraham it is forbidden. And see siman 457 seif 2: if one forgot to sell his chametz that he has in a special room on Erev Shabbat, he gives on Shabbat to gentiles the room with transfer of the key; and if it is impossible as a gift, he sells and it is not like buying and selling, since one does only to escape the prohibition of chametz.",
    "6:_": "(6) \"Betrothal meal\" etc. And it is difficult — behold, one does not make a betrothal meal on Erev Shabbat, and all the more so on Erev Pesach; and in siman 249 I wrote answers to this. Taz and Magen Avraham wrote that not specifically betrothal; rather the same law applies to the second meal of gifts, and likewise the purchase meal that they make now at the time of the match — it is a mitzvah. And see below in the customs seif 34.",
    "7:_": "(7) [Levush] \"And with less than a k'zayit\" etc. And one must say: and with less than this — meaning less than a k'beitzah; but after the sixth hour, when nullification is impossible, one must return; but with less than a k'zayit one need never return.",
    "8:_": "(8) [Levush] \"Where nullification, mitzvah\" etc. There it is explained that after the sixth hour, when it is impossible to nullify, one returns — for the positive commandment of \"tashbitu\" is more stringent, for every hour one transgresses upon it, which is not so with circumcision and Pesach; nevertheless it appears to me that saving a life is preferable to \"tashbitu\" of chametz, even on Pesach — for behold it overrides even Pesach, which has karet (Magen Avraham). And it is somewhat difficult, for he contradicts himself — he wrote that chametz is more stringent than circumcision and Pesach, since every hour one transgresses upon it, even though circumcision and Pesach have karet."
  },
  "output/siman_444/eshel-avraham/part-001.txt": {
    "1:_": "With meat and fish. And if one divides the second meal into two in the morning, it is possible that one does not fulfill according to the opinion that we require a third meal after minchah — Ramban siman 207.",
    "2:_": "He shall nullify it. Even though one does not declare ownerless on Shabbat — nevertheless with chametz they permitted it, for it is only a revelation of intent in general."
  },
  "output/siman_444/kaf-hachayyim/part-001.txt": {
    "1:_": "(1) [Seif 1] \"We search on the night of the 13th\" etc. — for on Shabbat night they cannot move the candle in order to search. Beit Yosef. Levush. And on the 13th day it is impossible to search, since it is forbidden to search by day l'chatchila, as is stated above siman 433 seif 3; see there.",
    "2:_": "(2) There. \"We search on the night of the 13th\" etc. And one blesses on burning chametz and nullifies all chametz that remains in his possession that he did not find in this search; and one is careful with chametz found in the search and with chametz that one leaves for eating to place it in a hidden place, so that small creatures or rodents not drag from it, as is stated in siman 434; see there. Maggid Mishneh seif 1; Razah seif 1; Chayei Adam general rule 129 seif 9; Kitzur Shulchan Aruch siman 115 seif 1.",
    "3:_": "(3) There, \"and we leave over food\" etc. And one must be careful to place it in a hidden place, as is stated above siman 434 seif 1; and see in our words there seif 3.",
    "4:_": "(4) There. \"And we leave over food\" etc. And one should not say that he burn everything before Shabbat and leave nothing, and on Shabbat eat matzah ashirah — for since it is not within everyone's ability to make matzah ashirah for all three meals, the Sages did not burden him. Beit Yosef.",
    "5:_": "(5) There. \"And we leave over food\" etc. And if one forgot to separate challah on Erev Shabbat from chametz bread that he baked for this Shabbat, it is forbidden to eat from it and he has no remedy. Magen Avraham siman 486 seif kaf 8. Chayei Yisrael siman 457 seif 9; Eliyah Rabbah in this siman seif 1; Makor Chaim seif 1; Maggid Mishneh seif 2; Razah seif 12; Chayei Adam general rule 129 seif 11. However, the Rav Netiv Chayim there in siman 486 challenged the words of Magen Avraham mentioned; and he wrote that it is fitting — these are the words of R' Chaim and the Rosh and Ba'al HaTerumot and Ra'avad and Ran and Ra'avatz, who ruled leniently to separate challah and give to a minor kohen; or to an adult who immersed for his keri; and even to an impure kohen, that he may nullify it in a majority and may eat, as is explained in Yoreh De'ah siman 323. And if there is no kohen, he eats and continues and leaves less than a k'zayit and covers it with a vessel until Motzei Yom Tov, like other chametz that remains where he has no non-Jew — siman 464 seif 5; see there. And likewise in She'eilat Ya'avetz siman 133; and in responsa Pnei Me'orot part 2 siman 96; and Beit Din that is on the table in this siman seif 1; and likewise in Sefer Bigdei Yesha siman 486; and in Chiddushei R' Akiva Eiger. And therefore it appears that where it is impossible to find other bread, one may rely on the lenient ones, so that Shabbat meals not be nullified; and see below siman 457 in the gloss and in our words there seif 16.",
    "6:_": "(6) There. \"Food for two meals for the sake of Shabbat night and in the morning of Shabbat day until a third of the day.\" Maggid Mishneh seif 2; and see above siman 443 seif 21 and seif 21.",
    "7:_": "(7) There. \"For the sake of Shabbat.\" And on this Shabbat they should not prolong in praises, lest the time of the prohibition of chametz arrive. Sefer Chassidim siman 514. Eliyah Rabbah seif 1. And it is good not to prolong on this Shabbat in the morning prayer and musaf; and it is obvious not to sing — only shorten as much as possible, so that one not stumble, Heaven forbid, in the prohibition of eating chametz after its time of prohibition. Maggid Mishneh seif 3; and see above in Shulchan Aruch siman 429 seif mem 2.",
    "8:_": "(8) There. \"Its time is after minchah.\" And nevertheless, also in the morning one should stop his meal into two (and that is, he blesses birkat hamazon — Shulchan Aruch siman 2 seif 2), for some say that one fulfills thus — Shulchan Aruch and Mordechai chapter 1 of Shabbos and Bach and Kol Bo. Magen Avraham seif kaf 1. However see above in Shulchan Aruch siman 291 seif 2, who ruled that even b'dieved one does not fulfill if he made it before the time of minchah; see there and in our words there seif 12."
  },
  "output/siman_444/peri-megadim/part-001.txt": {
    "1:_": "\"And we leave over\" — Taz. What he stated: the Tannaim who said \"we burn everything\" — leave food for two meals — so too Rashi Pesachim 49:1. However he explained thus, so that there not be four disputes — and R' Elazar of Bartuta and Pesachim 13:1. But it is not necessary that one must fulfill two meals with matzah ashirah — Magen Avraham, beginning of chapter, 1; or according to the one who says there is no prohibition of matzah on Erev Pesach except after the prohibition of chametz — and see Magen Avraham, the Tur thus practiced Rashi to burn everything before Shabbat and not eat matzah; Beit Yosef wrote that one eats matzah for pleasure — and this is like the Rosh; Beit Yosef siman 471 that before the fifth hour matzah is permitted; also he did not burden him with matzah ashirah; see there. And what Taz stated \"this burning\" etc., as is proven in siman 446 seif 2, that before the fifth hour one must give to a non-Jew, for afterward it is forbidden in tilul; however telling a non-Jew regarding muktzeh — siman 476 in Magen Avraham 11; and also shevut shevut in a place of mitzvah, as in siman 307 seif 5. And what he stated \"not the rest of the Shabbatot\" — it is not proven in 446; Magen Avraham there 2 — to scatter to the wind is forbidden, as in siman 319 siman 17; see there. Magen Avraham chapter 1 heh 3 — fine crumbs very thin — one may say it is grinding; see there. And Bach seif 3 in the name of Ba'al HaMaor that it is permitted to crumble on Shabbat; and one who forbids, that it is weekday labor — not so much. And it is possible in 446 it is proven that it is forbidden to crumble; and if so, there it will be explained. And Magen Avraham 446 seif 3 and 5 — when there is a non-Jew it is permitted in tilul; and the deed of feeding in Pesachim 49:1 — one may say in the fourth or fifth hour, as Magen Avraham stated in 446. And see seif 5 here; and if so, there it will be explained.",
    "2:א": "\"For the meal\" — Taz. Seemingly after the time of minchah — that is, six and a half, as in siman 291; and Magen Avraham here 1 and 291 in this matter 4 — that one divides also the morning meal into two, for some say one fulfills; and that is, he blesses birkat hamazon.",
    "2:ב": "\"If one forgot to separate challah from Erev Shabbat\" — Magen Avraham 486 seif 8; see there; and see Ba'er Heitev; and to declare it ownerless too is impossible. And according to the one who says bein hashemashot there is no prohibition to leave the challah of the oven — it has no measure; but we hold that bein hashemashot is forbidden — siman 457 in Magen Avraham. And if he separated challah on Erev Shabbat and forgot to burn and Shabbat arrived — at the fourth hour to a non-Jew it is forbidden to give, except to a minor kohen; but to an adult and to nullify in a majority one does not nullify on Shabbat — Magen Avraham 323:14 and 14:99 and in Peri there and 324. However one may say he declares it ownerless, or challah that is not his — one does not transgress upon it; see Pesachim how one separates challah in impurity; and to give to his dog one may say it is permitted; and see Beitzah 27:2 — one may say we do not burn kodshim on Yom Tov and Shabbat. And challah is distinct from it — Or Zarua chapter 1 of Terumot: challah of Israel is forbidden in benefit of adornment; and likewise tevel is forbidden in benefit of adornment — Tosafos Pesachim 9:1; and this requires further study — if so, one must throw everything into the sea and not to a non-Jew; and it is possible challah outside the Land is likewise and permitted in benefit. And if he separated challah intentionally he shall not eat; and in unwitting he eats — Or Zarua, may he rest in Eden, chapter 5 of Shabbat; and see what is stated in 323 in Magen Avraham 11; and in Taz chapter 5 he concluded there that d'rabbanan is permitted — if so, challah of the Land is different, for it is d'oraisa; not so challah of the oven d'rabbanan — one may say it is not so much of a remedy, even though it is impossible to eat thus, as Maggid Mishneh stated; and for the law, where he has no other bread except this that he forgot to take challah — one may side with what Taz stated there; if so, there in 486 it will be further explained.",
    "2:ג": "See in responsa Maharil siman 99 regarding the third meal — there is no positive commandment to override etc.; one may say it is a positive commandment of negligence — Tosafos Eruvin 100:1 s.v. \"matan\"; and see Magen Avraham in this matter in 291 regarding this; and siman 446 in Magen Avraham 2. In my book HaMagid I wrote the laws of Pesach that falls on Erev Pesach on Shabbat, and I noted them in Magen Avraham; and also here I will mention charoset and other things that must be prepared on Erev Shabbat, for on Yom Tov to crush in its normal way is somewhat forbidden; and b'dieved siman 484 — to roast meat and an egg in memory of the chagigah and Pesach; and one leaves for the second night of Shabbat on Erev Pesach — he roasts on Erev Shabbat, for on the first night of Yom Tov it is forbidden from Yom Tov to its fellow; and through cooking some say we do not say; and to fill a pot to cook many eggs — \"for specifically meat that is improved thus\" — Taz 473:4; see there. If it is permitted to put maror in water on Shabbat so that it not wither — Eliyah Rabbah 3 and 473:14 that it is permitted; and this requires further study regarding tilul and giving to drink, since it is not for the need of Shabbat it should be forbidden — siman 321 in Magen Avraham 13 and 454; and this requires further study if one inserts maror in the ground so that it not wither and not take root — see Mahariv chapter 5; and if so, there in 473 it will be explained; and Magen Avraham there seif 8 — if one forgot to roast the egg and meat, how shall he do on the night of Yom Tov; see there.",
    "2:ד": "\"Water\" — our drawn water one draws on the night of the fifth when Pesach falls on Sunday; and siman 455 for the law; and if so, there it will be explained. If one forgot to filter wine from raisins on Erev Shabbat — it is good to leave for the night of Yom Tov, for on Shabbat there are several concerns of bereirah and the like — siman 319 and siman 471. And siman 462 in Magen Avraham 8 — and a general stringency that one does not eat raisins on Pesach and filters beforehand; and here it is impossible — it is good to leave it to filter on the night of Yom Tov according to the ways explained in 471; and if so, there it will be explained.",
    "3:_": "\"Before\" — Taz; and Magen Avraham 471 seif 1 — a quarter of the day; and seif 5 — what is matzah ashirah — in siman 486. See responsa Knesset Yechezkel end of part 1 chalef resh — when Sunday falls on Motzei Shabbat he says \"from the sacrifices and Pesachim,\" which refers to the coming year; and Mahariv chapter 5 — his explanation: when Pesach will come on Motzei Shabbat — that is, next year; build there; and siman 473 in Taz and Magen Avraham seif 30; and one who examines Mahariv chapter 5 \"when it comes on Shabbat one should not read the Haggadah alone, and when it comes on Motzei Shabbat\" etc. — it implies this year; and if so, there it will be explained.",
    "4:_": "\"Porridge\" — Taz; and Magen Avraham 5; and Efrayim.",
    "5:_": "\"To the public domain\" — Taz; and Magen Avraham 7; and Eshel Avraham to resolve what is stated in the gloss in 325 seif 2; see there. And outside the techum, which is d'rabbanan, for the sake of mitzvah it is shevut shevut and permitted — one may say. And what Chayei Yisrael 1 and Eliyah Rabbah 5 wrote: if one forgot to sell, he can sell on Shabbat through meshichah — and see from Tosafos Eruvin 66:1 s.v. \"yafeh\"; and this requires further study somewhat. For rental in Eruvin was a distinguishing mark in general to permit tilul — not so here; and a purchase made in prohibition — some say it is not a purchase in truth — R' Chaim and 14; and siman 483; and this requires further study.",
    "6:_": "\"And covers\" — Taz; and Magen Avraham 446:3 that at the fifth hour it is permitted to move and to give the chametz to a non-Jew — and this appears to be the opinion of Taz here, therefore he explained where there is no non-Jew or many and it is impossible to give a little etc.; see there. And to scatter and to crumble — there is a dispute whether it is permitted; but to a river or to a bathroom it is permitted — siman 446; and at the sixth hour to tell a non-Jew to throw to the river — one may say shevut shevut in a place of mitzvah is permitted — siman 446; and if so, there it will be further explained. And it also deals with where there is no dog to give; and therefore he covers the vessel; and see what is stated there in seif 7 from this.",
    "7:_": "\"One must\" — Taz. And on Erev Shabbat one need not nullify — Magen Avraham 3; and Chayei Yisrael 4; and likewise in Levush in the gloss. And what is stated in seif 5 \"if remains he nullifies it\" — in any event nullification is required; only here if it is impossible through giving to a non-Jew he covers the vessel and includes within the nullification etc.; in drawing water siman 455; and Or Zarua here 1; and if so, there it will be explained. They wrote, may they rest in Eden, that the shaliach tzibbur should not prolong in the morning prayer. The rabbi expounds on the Shabbat before it. In responsa Knesset Yechezkel end of part 1 chalef chet — on Shabbat on Erev Pesach he warns the householder regarding parashat challah, for the reason that we do not mention now challah outside the Land — eat and go and afterward separate — and this language on Shabbat on Erev Pesach; see there siman 200 and 486 in Magen Avraham 8.",
    "8:_": "\"Meal\" — Taz Pesachim 49:1; and the Beit Yosef holds that R' Yehuda and R' Yosi disagree also regarding the second of betrothal — also according to R' Yosi it is a mitzvah; and even the meal of gifts — according to R' Yehuda the third is a mitzvah; that third without gifts R' Yosi agrees is not a mitzvah (Bach; and one may say first and second are dear to him that his heart be coarse in it, and from here onward not). And this is what is stated in the Gemara: and now that Erev Pesach — this is explained thus in the baraita — except the second of betrothal without gifts; and regarding both they disagree. And it said \"and now that Erev Pesach\" to say that it is more reasonable to say that the Mishnah is R' Yehuda, that an unspecified betrothal meal implies the first — and the halachah is so. And this is what the Tur stated: first meal of betrothal or of gifts; and he ruled regarding the second of betrothal like R' Yehuda according to the plain meaning of the Mishnah; and gifts like R' Yosi, that both are included — see there. For if like Rashi's explanation, it should have said to eat betrothal meal or gifts or first meal betrothal and second of gifts — and Taz explained like Bach and like Rashi, may he rest in Eden, that it is one dispute; and likewise Magen Avraham 9 like Bach; and if so, there it will be explained. And a meal at the time of match that they call knas — Eliyah Rabbah: see responsa Chavot Yair siman 70 that certainly it is not a meal of mitzvah. And what Eliyah Rabbah 7 and Chayei Yisrael 10 wrote regarding match with purchase — one may say that they send gifts then, as Magen Avraham 9 stated; but match without gifts — not; and see Ba'er Heitev. And for what he stated that specifically with gifts — and see Chok Yisrael, who expanded; see there. And Magen Avraham 9; and if so, there it will be explained."
  },
  "output/siman_444/ateret-zekenim/part-001.txt": {
    "1:_": "\"Rather with matzah ashirah\" etc. And there are those who forbid matzah ashirah on the 14th day, for it is written \"in the evening you shall eat matzot\" — and matzah ashirah is also called matzah, for behold all the meal-offerings come as matzah and they were kneaded in oil. And it is possible to distinguish between matzah ashirah that has a mixture of water, through which a person fulfills under duress and it is forbidden on the 14th, and between matzah ashirah kneaded in fruit juice without water — then it does not come to leavening and one does not fulfill with it even under duress — and that matzah one should permit on the 14th before the tenth hour.",
    "5:_": "\"And he covers a vessel over it.\" And it appears that here it means: if he can give it to a non-Jew it is better; and if it is impossible to give it to a non-Jew, then he covers a vessel over it. And what is stated \"on condition that he not go out to the public domain\" — the same law applies in an unspecified case too, it is permitted; only one does not give to him on condition. And such is the agreement of all the poskim. And the Rav's wording of the gloss of Me'ironi took, who wrote in chapter 3 of Hilchot Chametz uMatzah; and with this is resolved that there is no difficulty from here on siman 325 seif 3 in the gloss (gloss in the name of Maharatz Schiff in Magen Avraham seif kaf 5). However if there was a pledge in his hand etc. — likewise with a pledge; and the borrower must pay him; end of his words; and this requires further study. And it appears to me that certainly he need not pay him — for what we say in Bava Kamma that one says to him \"behold yours is before you\" — because if you say that the depositor shall pay, then the depositor would benefit from what he receives payment; and if so, the depositor would say to the depositor: behold, you too are commanded not to benefit from chametz that passed over Pesach and are obligated in the mitzvah of burning chametz — therefore he says to him \"behold yours is before you\" and fulfill with your money the mitzvah of burning chametz; and he does not wish to pay him money. Not so here regarding a pledge — you wish to take the money from the borrower; if so, the borrower too would say to the lender: behold, you too are commanded not to benefit from chametz that passed over Pesach, and you can fulfill the mitzvah of burning chametz — why then do you wish to receive payment? And if so, certainly one may not take by force from the borrower; and it is simple. And if so, what Ba'al Magen David seif kaf 5 end of seif 4 stated, who also ruled that the borrower is obligated to pay — it is not so; and it is simple. Also what Ba'al Magen David seif kaf 5 end of the seif stated, and these are his words: and according to this he should not have written here \"if they acquired all of it\"; end of his words — it appears to me there is no difficulty at all, for since he does not say \"if he acquired\" but says \"if they acquired\" — it implies that it refers to above, that it was deposited with them; and if so, it is not a chametz-owner of transgressors; and it is simple (Maharar Nata Shapiro)."
  },
  "output/siman_444/chatam-sofer/part-001.txt": {
    "1:_": "In Magen Avraham seif kaf 9 — and it appears to me that it is called a meal of mitzvah. NB: and a circumcision meal and the night before it in Ashkenaz — see what is stated below siman 640 seif kaf 15; and see Shach Yoreh De'ah end of siman 178.",
    "2:_": "There — Chayei Yisrael seif kaf 8 — and it is possible that even... NB: see in Sefer Beit Meir siman 136 seif 7 at its end, who rejected the proofs of Chayei Yisrael from Tosafos Eruvin with good reason and opinion; see there [from the Gaon, may he rest in Eden].",
    "3:_": "There — in Magen Avraham seif kaf 11 — not so with circumcision. NB: and he asked in Sefer Even HaEzer — behold, one who goes to slaughter his Pesach — there is karet if he does not make Pesach; and he asked in Sefer Ba'er Heitev in the name of the Gaon R' Shaul, may he rest in Eden — behold, in any event it is impossible to make Pesach because of \"you shall not slaughter upon chametz the blood of My sacrifice.\" And in my humble opinion it appears that this is specifically with his chametz; but with a deposit and he accepted responsibility — for on Pesach he transgresses with his own because of what is written \"it shall not be found in your domain\"; but because of \"you shall not slaughter\" he does not transgress — if so, in this case he slaughters his Pesach and does not return to burn chametz that was deposited with him; and with this nullification does not help even before the sixth hour. And see in responsa She'elat Aryeh; and now I found likewise in Tzelach; see there.",
    "4:_": "In Magen Avraham seif kaf 13 — and to this the Tur intended. NB: for in the first passage they wrote \"one who goes to make an eruv\" — meaning with his legs to the domain; but in the second passage they wrote \"went to the evening\" and they did not write to make an eruv, but to the evening — and that is with bread, since he goes to his rabbi; and it is simple.",
    "5:_": "There seif kaf 14 — \"as in Tosafos.\" NB: meaning that it is not less than kodshim, that one does not return for less than a k'zayit; see there in Tosafos s.v. \"vechachamim.\""
  },
  "output/siman_444/rabbi-akiva-eiger/part-001.txt": {
    "1:_": "Seif 5 — \"and he covers a vessel over it until.\" It is difficult to me — why is covering a vessel permitted? Behold, he can throw it outside or to the bathroom; and this case is different on Yom Tov, where tilul is forbidden; and this requires further study.",
    "2:_": "Taz seif kaf 5 — \"except that he must not take it out.\" See in Sefer Tosafot Shabbat siman 266 seif kaf 5.",
    "3:_": "Magen Avraham seif kaf 11 — and it implies that if it is from the beginning. And likewise explicitly in She'eilot chapter 16 siman 73.",
    "4:_": "Magen Avraham seif kaf 14 (\"as in Tosafos\"). This is not proof, for there with kodshim one does not transgress the negative commandment after it was already permitted; but here at every moment and moment one transgresses biblically; and even at half the measure there is a biblical prohibition according to many poskim. See Tosafos Shabbat siman 266 seif 5."
  },
  "output/siman_444/yad-ephraim/part-001.txt": {
    "1:_": "In Magen Avraham seif kaf 9 — and it is from the Yerushalmi; and it is etc. — meaning that the Yerushalmi in these laws disagrees with our Talmud, for behold the Yerushalmi holds that it is forbidden to carry on Erev Shabbat; and in our Gemara in Moed Katan it is proven that even on Erev Regel it is permitted; see above siman 249. And if so, the same applies regarding a betrothal meal; and the Yerushalmi disagrees in this with our Shas — and if so, one should not rule like the Yerushalmi.",
    "2:_": "There seif kaf 11 — and it implies that if it is from the beginning of the sixth hour and above etc. — this requires further study; for what is stated \"from the beginning of the sixth hour\" — even though he cannot nullify then, since d'rabbanan it is forbidden in benefit, nevertheless the positive commandment of \"tashbitu\" is not present except after the tenth hour; and if so, at the beginning of the sixth hour he need not return immediately, for the language \"the positive commandment of tashbitu is more stringent\" applies only from the sixth hour and above — if not where he would need to remain in performing the mitzvah and in the interim the sixth hour would pass and he would transgress the positive commandment of tashbitu. And also this requires further study — for it is possible that he should not transgress the mitzvah that is now before us, even though through this he will come to nullify the positive commandment of tashbitu — nullification automatically; and for this reason he should not leave the mitzvah before us. And that which he stated \"he shall nullify it in his heart\" — that is where it is possible through nullification to do so; but from the sixth hour and above, since the positive commandment of tashbitu has already taken effect, one may well say it is more stringent.",
    "3:_": "In Taz seif kaf 9. The Rosh asked — behold, one does not make an eruv etc. — meaning that in the Mishnah it states for shevitat reshut; and Rashi explained that one makes eruvei techumin."
  },
  "output/siman_444/shaarei-teshuvah/part-001.txt": {
    "1:_": "\"Food.\" Ba'er Heitev; and see She'eilat Ya'avetz siman 133 — he also challenged Ba'er Heitev; and see there that he wrote: that which implies from Magen Avraham that even to nullify oneg Shabbat, where he has no other bread — the law is not so; except in such a case it fits well to leave the vessels of separation in the mouth and hands without a blessing — and this is the separation, and a minor eats it, or an adult who immersed, or throw it in the pouch of the kohen; and where there is none, one should permit through nullification in a majority even for a non-Jew on Erev Shabbat. And in responsa Pnei Me'orot part 2 siman 36 he also wrote not like Magen Avraham; and he wrote that that which is forbidden to separate on Yom Tov — there, since he has another remedy to eat a little and leave a little; but on Erev Pesach that falls on Shabbat he does not have this remedy — one should permit through separation according to what we hold, challah outside the Land: eat and go etc., for the separation is not a d'oraisa remedy; and therefore it is well permitted to separate on Shabbat and give to a minor kohen and eat on Erev Shabbat.",
    "2:_": "(In the gloss) \"In lands\" etc. And see in responsa Noda B'Yehuda siman 21 what he asked on this — that there is no proof from Pesach itself to Erev Pesach; and see there that he wrote that until noon it is certainly permitted to eat matzah ashirah on Erev Pesach; and one who instructs to be lenient all day, even without need of a sick person or elder — he did not lose if it is in any event a slight need; but on Pesach itself they are stringent on Erev Shabbat.",
    "3:_": "In Shulchan Aruch seif 2 \"it is good to burn\" etc. And see in responsa Chaim Sha'al part 2 siman 38 sign 84 in the name of Sefer Noda B'Yehuda — this requires further study regarding melachah on Erev Shabbat, whether its law is like other Erev Pesach or one should be lenient; and he wrote that in derashot Maharil he wrote that one who wishes to be stringent shall be stringent; but the owner of such a case in the order of his Haggadah called Pesach Me'uvin wrote that he did not see people careful even as a stringency; and likewise in Mishna Berurah in the name of Zera Emet that it is permitted; and see there."
  },
  "output/siman_444/netiv-chayim/part-001.txt": {
    "1:_": "(In Shulchan Aruch seif 1.) \"The 14th when it falls.\" NB: see siman 446 seif kaf 23."
  },
  "output/siman_444/levushei-serad/part-001.txt": {
    "1:_": "Magen Avraham seif kaf 9 — that a meal whose time is fixed on Erev Shabbat is permitted; and the meal of gifts etc. — so it should read.",
    "2:_": "Seif kaf 11 — and Rambam wrote, and these are his words — so it should read."
  }
};
